<script setup>
import {computed,ref,useId,watch} from 'vue'
import SimulationControls from './SimulationControls.vue'
import {adversarialExamples,createGameTree,traceAdversarial,exactGameValue,adversarialCode,adversarialLine} from '../services/adversarial-search.mjs'
const props=defineProps({initialMode:{type:String,default:'alphabeta'},initialExample:{type:String,default:'classic'}})
const mode=ref(props.initialMode),exampleId=ref(props.initialExample),order=ref('original'),depth=ref('all'),step=ref(0),custom=ref(null),input=ref(''),error=ref(''),copied=ref(false),inspected=ref(null)
const marker='adversarial-'+useId().replace(/[^a-zA-Z0-9_-]/g,'')
const example=computed(()=>custom.value||adversarialExamples.find(e=>e.id===exampleId.value)||adversarialExamples[0])
const tree=computed(()=>createGameTree(example.value.tree))
const limit=computed(()=>depth.value==='all'?Infinity:Number(depth.value))
const frames=computed(()=>traceAdversarial(tree.value,mode.value,limit.value,order.value))
const state=computed(()=>frames.value[Math.min(step.value,frames.value.length-1)])
const node=computed(()=>tree.value.nodes.find(n=>n.id===state.value.id))
const resetKey=computed(()=>JSON.stringify([example.value,mode.value,depth.value,order.value]))
watch(resetKey,()=>{step.value=0;inspected.value=null;copied.value=false})
watch(exampleId,()=>{custom.value=null;error.value='';input.value=JSON.stringify(adversarialExamples.find(e=>e.id===exampleId.value).tree,null,2)},{immediate:true})
const fmt=n=>n===Infinity?'+∞':n===-Infinity?'−∞':String(n)
const record=n=>state.value.records[n.id]
const label=n=>{const r=record(n);if(r?.bound==='interval')return r.low===r.high?'= '+fmt(r.low):r.low===-Infinity&&r.high===Infinity?'Chưa đủ cận':r.low===-Infinity?'≤ '+fmt(r.high):r.high===Infinity?'≥ '+fmt(r.low):fmt(r.low)+' … '+fmt(r.high);return r?.value!==undefined?(r.bound==='lower'?'≥ ':r.bound==='upper'?'≤ ':'= ')+fmt(r.value):state.value.pruned.includes(n.id)?'Đã cắt':n.type==='LEAF'?'Cho sẵn '+n.utility:'Chưa có giá trị'}
const status={enter:'Gọi tìm kiếm tại nút hiện tại. Ghi cửa sổ alpha và beta của lời gọi.',terminal:'Đã tới trạng thái kết thúc. Đọc lợi ích theo góc nhìn MAX.',cutoff:'Chạm giới hạn độ sâu. Dùng điểm đánh giá cho cây bị cắt ở độ sâu này, không coi đó là lợi ích thật của ván đấu.',choose:'Đi xuống nút con kế tiếp theo thứ tự duyệt.',update:'Nhận kết quả từ nút con, cập nhật lựa chọn hiện tại và các ngưỡng.',prune:'Alpha đã lớn hơn hoặc bằng beta. Bỏ qua các nút con còn lại vì chúng không thể cải thiện lựa chọn của tổ tiên.',return:'Trả kết quả cho nút cha. Nhãn cận cho biết mức độ thông tin đã chứng minh.',complete:'Đã hoàn tất tìm kiếm với cửa sổ gốc đầy đủ.',budget:'Chạm giới hạn thao tác của bộ xem. Chưa có kết luận hoàn tất.'}
const focus=computed(()=>{
 const selected=inspected.value&&tree.value.nodes.find(n=>n.id===inspected.value)
 if(selected)return selected.type==='LEAF'?tree.value.nodes.find(n=>n.id===selected.parent)||selected:selected
 if(!node.value)return tree.value.nodes[0]
 return node.value.type==='LEAF'?tree.value.nodes.find(n=>n.id===node.value.parent)||node.value:node.value
})
const children=computed(()=>focus.value.children.map((id,i,ids)=>({...tree.value.nodes.find(n=>n.id===id),x:ids.length===1?180:45+i*270/(ids.length-1)})))
const summary=computed(()=>['minimax','alphabeta'].map(m=>{const f=traceAdversarial(tree.value,m,limit.value,order.value);return {mode:m,end:f.at(-1)}}))
const line=computed(()=>adversarialLine(state.value.phase))
function apply(){try{const t=JSON.parse(input.value);createGameTree(t);custom.value={id:'custom',title:'Cây tự nhập',tree:t};error.value='';step.value=0}catch(e){error.value=e.message}}
async function copy(){try{await navigator.clipboard.writeText(adversarialCode.join('\n'));copied.value=true}catch{error.value='Chưa chép được mã. Bạn có thể chọn mã trong khung bên dưới.'}}
function tokens(row){return row.split(/('(?:[^'\\]|\\.)*'|\b(?:export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null)\b|\b\d+\b)/g).filter(Boolean).map(text=>({text,kind:text.startsWith("'")?'string':/^(export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null)$/.test(text)?'keyword':/^\d/.test(text)?'number':''}))}
</script>

<template>
<figure class="lab adversarial-lab" aria-label="Mô phỏng Minimax và cắt tỉa alpha beta">
 <div class="game-settings"><label>Thuật toán<select v-model="mode"><option value="minimax">Minimax · Xét mọi nhánh</option><option value="alphabeta">Alpha–Beta · Cắt tỉa</option></select></label><label>Cây ví dụ<select v-model="exampleId"><option v-for="e in adversarialExamples" :key="e.id" :value="e.id">{{ e.title }}</option></select></label><label>Thứ tự nút con<select v-model="order"><option value="original">Trái sang phải</option><option value="reverse">Phải sang trái</option></select></label><label>Độ sâu tối đa<select v-model="depth"><option value="all">Đến lá</option><option v-for="d in 5" :key="d" :value="String(d-1)">{{ d-1 }} hành động</option></select></label></div>
 <p class="convention">R là nút gốc của MAX. Mỗi chữ số chỉ vị trí nút con, ví dụ R12 là con thứ hai của R1. Lợi ích luôn theo góc nhìn MAX. Khi hòa, giữ nút gặp trước. Điểm đánh giá mặc định ở nút trong là 0, riêng ví dụ độ sâu có điểm 5 và 4. Kiểm tra kết thúc trước khi kiểm tra giới hạn độ sâu.</p>
 <SimulationControls v-model="step" :max="frames.length-1" :reset-key="resetKey" />
 <p class="game-status" role="status" aria-live="polite">{{ status[state.phase] }}<span v-if="node"> Nút {{ node.id }} · {{ node.type==='LEAF'?'Kết thúc':node.type }}. {{ label(node) }}.</span></p>
 <div v-if="state.result" class="game-result">Giá trị gốc: {{ fmt(state.result.value) }}. Lựa chọn: {{ state.result.move||'Không có hành động ở nút này' }}. {{ limit===Infinity?'Đã tìm tới trạng thái kết thúc.':'Đây là kết quả của cây ở độ sâu đã chọn.' }}</div>
 <div class="game-panels">
  <section class="game-tree"><div class="game-panel-title"><h4>Nhánh đang quan sát: {{ focus.id }}</h4><button v-if="inspected" type="button" @click="inspected=null">Theo bước chạy</button></div>
   <svg viewBox="0 0 360 290" role="img" aria-label="Nút đang quan sát và các nút con, với loại MAX MIN cùng các giá trị đã biết">
    <defs><marker :id="marker" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M1 1 9 5 1 9"/></marker></defs>
    <g v-for="c in children" :key="c.id" :class="{pruned:state.pruned.includes(c.id),active:state.child===c.id}"><path :d="`M180 82 Q180 125 ${c.x} 176`" :marker-end="`url(#${marker})`"/></g>
    <g class="tree-node" :class="{active:state.id===focus.id}" @click="inspected=focus.parent"><path v-if="focus.type==='MAX'" d="M180 22 149 80 211 80Z"/><path v-else-if="focus.type==='MIN'" d="M149 25 211 25 180 83Z"/><rect v-else x="153" y="28" width="54" height="45" rx="6"/><text x="180" y="61" text-anchor="middle">{{ focus.id }}</text><text x="180" y="105" text-anchor="middle">{{ focus.type }} · {{ label(focus) }}</text></g>
    <g v-for="c in children" :key="c.id" class="tree-node" :class="{active:state.id===c.id,pruned:state.pruned.includes(c.id)}"><path v-if="c.type==='MAX'" :d="`M${c.x} 173 ${c.x-28} 225 ${c.x+28} 225Z`"/><path v-else-if="c.type==='MIN'" :d="`M${c.x-28} 176 ${c.x+28} 176 ${c.x} 228Z`"/><rect v-else :x="c.x-26" y="180" width="52" height="42" rx="5"/><text :x="c.x" y="208" text-anchor="middle">{{ c.id }}</text><text :x="c.x" y="249" text-anchor="middle">{{ c.type==='LEAF'?'Lá':c.type }}</text><text :x="c.x" y="275" text-anchor="middle">{{ label(c) }}</text></g>
   </svg>
   <p>Tam giác lên: MAX. Tam giác xuống: MIN. Hình vuông: Kết thúc. Cận ≥ hoặc ≤ không phải một giá trị chính xác. Chọn nút trong danh sách để xem nhánh khác.</p>
   <details class="tree-list"><summary>Toàn bộ cây và thông tin đã biết</summary><ul><li v-for="n in tree.nodes" :key="n.id" :class="{pruned:state.pruned.includes(n.id),active:state.id===n.id}" :style="{'--tree-depth':n.depth}"><button type="button" @click="inspected=n.id">{{ n.id }} · {{ n.type==='LEAF'?'Lá':n.type }}</button><span>{{ label(n) }}</span></li></ul></details>
  </section>
  <section class="game-stack"><h4>Ngăn xếp lời gọi</h4><p>Alpha và beta là ngưỡng lựa chọn của tổ tiên, không phải khoảng chắc chắn chứa giá trị thật của mọi nút con.</p><ol v-if="state.stack.length"><li v-for="(f,i) in state.stack" :key="i"><strong>{{ f.id }}</strong><span>v = {{ fmt(f.value) }}</span><span>α = {{ fmt(f.alpha) }} · β = {{ fmt(f.beta) }}</span></li></ol><p v-else>Ngăn xếp rỗng.</p><p>Đã thăm {{ state.visits }} nút.</p><p>Đã đánh giá {{ state.evaluated.length }} nút: {{ state.evaluated.join(', ')||'Chưa có' }}.</p><p>Đã cắt {{ state.pruned.length }} nút: {{ state.pruned.join(', ')||'Chưa có' }}.</p></section>
 </div>
 <details class="game-comparison"><summary>Đối chiếu Minimax và Alpha–Beta</summary><p v-for="r in summary" :key="r.mode">{{ r.mode==='minimax'?'Minimax':'Alpha–Beta' }}: Giá trị {{ fmt(r.end.result?.value) }}, chọn {{ r.end.result?.move||'Không có' }}, thăm {{ r.end.visits }} nút, đánh giá {{ r.end.evaluated.length }} lá hoặc điểm dừng.</p><p>Thứ tự duyệt chỉ có thể đổi số nút được xét và lựa chọn giữa các nước hòa điểm, khi cây và điểm đánh giá được giữ nguyên.</p><details><summary>Giá trị thật của cây để kiểm chứng</summary><p>Phép tính đối chiếu dưới đây duyệt riêng toàn bộ cây, không hướng dẫn thuật toán phía trên. Chi phí của nó không được tính vào số nút tìm kiếm.</p><p v-for="n in tree.nodes" :key="n.id">{{ n.id }}: {{ exactGameValue(tree,n.id) }}.</p></details></details>
 <section class="game-code"><div class="code-title"><h4>JavaScript · Dòng {{ line+1 }}</h4><button type="button" @click="copy">{{ copied?'Đã chép mã':'Chép mã' }}</button></div><pre><code><span v-for="(t,j) in tokens(adversarialCode[line]||'')" :key="j" :class="t.kind">{{ t.text }}</span></code></pre><details><summary>Xem chương trình thực thi đầy đủ</summary><p>Hàm sinh chạy tìm kiếm đệ quy thật. snap chỉ sao chép thông tin để quan sát. Bộ xem lưu lịch sử để quay lại, nên lượng bộ nhớ này không đại diện cho bộ nhớ của Minimax hay Alpha–Beta.</p><pre><code><span v-for="(row,i) in adversarialCode" :key="i" class="code-row" :class="{active:i===line}"><span aria-hidden="true" class="line-number">{{ i+1 }}</span><span><span v-for="(t,j) in tokens(row)" :key="j" :class="t.kind">{{ t.text }}</span></span></span></code></pre></details></section>
 <details class="game-edit"><summary>Nhập cây và thay các lợi ích</summary><p>Mảng lồng nhau biểu diễn các tầng, số là lợi ích lá. Có thể dùng {"eval": 5, "children": [...]} cho nút có điểm đánh giá. Tối đa 45 nút, mỗi nút có tối đa 3 con và tối đa 4 hành động từ gốc.</p><label>Cây JSON<textarea v-model="input" rows="8" spellcheck="false"/></label><button type="button" @click="apply">Áp dụng và đặt lại</button><p v-if="error" role="alert">{{ error }}</p></details>
 <details class="lab-tasks"><summary>Dự đoán trước khi chạy</summary><ol><li>Chạy cây ba nhánh và chỉ ra vì sao hai lá 4, 6 có thể bị bỏ qua.</li><li>Chuyển sang cây “Giá trị trả về chỉ là cận”. Vì sao nút đã trả 100 vẫn có thể mang giá trị thật 150?</li><li>Đảo thứ tự duyệt. Giá trị gốc và số lá đã đọc thay đổi thế nào?</li><li>Chọn ví dụ ước lượng nông, so sánh giới hạn một và hai hành động.</li></ol></details>
</figure>
</template>

<style scoped>
.adversarial-lab{min-width:0}.game-settings{display:grid;grid-template-columns:1fr 1fr;gap:12px}.adversarial-lab label{display:grid;gap:6px}.adversarial-lab :is(button,select,textarea){min-height:44px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);padding:8px;font:var(--fs-small)/1.6 var(--font-ui);max-width:100%;box-sizing:border-box}.adversarial-lab select{width:100%}.adversarial-lab :is(button,select,input,textarea):focus-visible{outline:3px solid var(--tim);outline-offset:3px}.adversarial-lab button,.adversarial-lab summary{cursor:pointer}.adversarial-lab p,.convention,.adversarial-lab li,.adversarial-lab summary{font:var(--fs-small)/1.7 var(--font-ui);overflow-wrap:anywhere}.game-status,.game-result{padding:12px;background:var(--tim-soft);border-left:3px solid var(--tim);line-height:1.7;margin:14px 0}.game-panels{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.game-panels section{padding:12px;border:1px solid var(--rule);border-radius:var(--radius);min-width:0}.adversarial-lab h4{font:600 var(--fs-ui)/1.6 var(--font-ui);margin:0 0 10px}.game-panel-title,.code-title{display:flex;align-items:center;gap:10px;justify-content:space-between;flex-wrap:wrap}.game-tree svg{width:100%;margin:0;border:0;max-height:none}.game-tree svg path{fill:none;stroke:var(--ink-2);stroke-width:1.4}.game-tree .tree-node :is(path,rect){fill:var(--paper);stroke:var(--ink-2);stroke-width:1.4}.game-tree text{fill:var(--ink);font:15px var(--font-ui)}.game-tree .active :is(path,rect){stroke:var(--tim);stroke-width:2.5;fill:var(--tim-soft)}.game-tree .pruned :is(path,rect){stroke-dasharray:4 4}.tree-list ul{list-style:none;padding:0;margin:0;display:grid;gap:5px}.tree-list li{padding-left:calc(var(--tree-depth)*10px);display:flex;gap:8px;align-items:center;flex-wrap:wrap}.tree-list .pruned{opacity:.65}.game-stack ol{list-style:none;padding:0;display:grid;gap:8px}.game-stack li{display:grid;gap:4px;padding:10px;border:1px solid var(--rule);border-radius:var(--radius)}.adversarial-lab details{margin-top:16px}.adversarial-lab summary{min-height:44px}.game-code{min-width:0;margin-top:20px}.game-code pre{white-space:pre-wrap;overflow-wrap:anywhere;overflow:visible;padding:12px;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);font:13px/1.8 var(--font-code);color:var(--ink)}.game-code code{font:inherit}.code-row{display:grid;grid-template-columns:3ch minmax(0,1fr);gap:8px}.code-row.active{background:var(--tim-soft);border-left:3px solid var(--tim)}.line-number{color:var(--ink-2);user-select:none}.keyword{color:var(--tim);font-weight:600}.string{color:var(--xanh)}.number{color:var(--do)}.game-edit textarea{display:block;width:100%;font:12px/1.7 var(--font-code);margin:8px 0}@media(max-width:700px){.game-settings,.game-panels{grid-template-columns:minmax(0,1fr)}.adversarial-lab{padding:12px}.game-panels section{padding:8px}}
</style>
